export type ParsedClawbackInstruction<
  TProgram extends string = typeof VESTING_POSITIONS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    creator: TAccountMetas[0];
    campaign: TAccountMetas[1];
    collection: TAccountMetas[2];
    updateAuthority: TAccountMetas[3];
    asset: TAccountMetas[4];
    mint: TAccountMetas[5];
    campaignAta: TAccountMetas[6];
    creatorAta: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
    associatedTokenProgram: TAccountMetas[10];
    mplCoreProgram: TAccountMetas[11];
  };
  data: ClawbackInstructionData;
};

export function parseClawbackInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedClawbackInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      creator: getNextAccount(),
      campaign: getNextAccount(),
      collection: getNextAccount(),
      updateAuthority: getNextAccount(),
      asset: getNextAccount(),
      mint: getNextAccount(),
      campaignAta: getNextAccount(),
      creatorAta: getNextAccount(),
      systemProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      mplCoreProgram: getNextAccount(),
    },
    data: getClawbackInstructionDataDecoder().decode(instruction.data),
  };
}
